/** 
 * Starts the bundle.
 * @param bc BundleContext
 * @throws Exception -
 */
public void start(BundleContext bc) throws Exception {
  bundleContext=bc;
  Hashtable<String,String> props=new Hashtable<String,String>();
  props.put(ResourcePack.RESOURCE_NAME,SkinPack.RESOURCE_NAME_DEFAULT_VALUE);
  bundleContext.registerService(SkinPack.class.getName(),this,props);
}
